def calculate_average_monthly_savings(income, expenses):
    if len(income) != len(expenses) or len(income) != 12:
        return None

    total_savings = 0
    for i in range(12):
        if not isinstance(income[i], (int, float)) or not isinstance(expenses[i], (int, float)) or income[i] < 0 or expenses[i] < 0:
            return None
        monthly_savings = income[i] - expenses[i]
        total_savings += monthly_savings

    if total_savings < 0:
        return None

    average_savings = total_savings / 12
    return average_savings

